#!/usr/bin/env python3
"""Detect available PDF libraries."""
import importlib.util

for name in ["pypdf", "PyPDF2", "pdfplumber", "pikepdf", "fitz", "reportlab"]:
    spec = importlib.util.find_spec(name)
    print(f"{name}: {'available' if spec else 'NOT available'}")

"""Merge report_part1.pdf and report_part2.pdf into combined_report.pdf.

Pure-Python (standard library only) PDF merger: parses each input PDF's
object structure and xref table (classic xref tables and xref streams),
renumbers objects, rebuilds a single page tree and catalog, and writes a
valid merged PDF with a classic xref table.

Fails with a clear message if the inputs cannot be parsed. No unrelated
side effects.
"""
import os
import re
import sys
import zlib

INPUT_FILES = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT_FILE = "combined_report.pdf"

WS = b"\x00\t\n\x0c\r "
DELIM = b"()<>[]{}/%"
REF_RE = re.compile(rb"(\d+)\s+(\d+)\s+R")


def skip_ws(buf, i):
    n = len(buf)
    while i < n:
        c = buf[i:i + 1]
        if c in WS:
            i += 1
        elif c == b"%":
            j = buf.find(b"\n", i)
            i = n if j < 0 else j + 1
        else:
            break
    return i


def skip_literal(buf, i):
    """i points at '('; return index just after the matching ')'."""
    depth = 0
    n = len(buf)
    while i < n:
        c = buf[i:i + 1]
        if c == b"\\":
            i += 2
            continue
        if c == b"(":
            depth += 1
        elif c == b")":
            depth -= 1
            if depth == 0:
                return i + 1
        i += 1
    return n


def find_keyword(buf, start, kw, prev_ws_only=False):
    """Find a standalone keyword outside strings, hex strings and comments."""
    n = len(buf)
    i = start
    klen = len(kw)
    while i < n:
        c = buf[i:i + 1]
        if c == b"%":
            j = buf.find(b"\n", i)
            i = n if j < 0 else j + 1
            continue
        if c == b"(":
            i = skip_literal(buf, i)
            continue
        if c == b"<":
            if buf[i:i + 2] == b"<<":
                i += 2
                continue
            j = buf.find(b">", i)
            i = n if j < 0 else j + 1
            continue
        if c == b"\\":
            i += 2
            continue
        if buf[i:i + klen] == kw:
            if i > 0:
                p = buf[i - 1:i]
                prev_ok = p in WS or (not prev_ws_only and p in DELIM)
            else:
                prev_ok = True
            after = i + klen
            if after >= n:
                next_ok = True
            else:
                q = buf[after:after + 1]
                next_ok = q in WS or q in DELIM
            if prev_ok and next_ok:
                return i
        i += 1
    return -1


def parse_value(buf, i):
    """Parse one PDF value starting at i; return (value, new_index)."""
    i = skip_ws(buf, i)
    n = len(buf)
    if i >= n:
        raise ValueError("unexpected end of input")
    c = buf[i:i + 1]
    if c == b"/":
        j = i + 1
        while j < n and buf[j:j + 1] not in DELIM + WS:
            j += 1
        name = re.sub(rb"#([0-9a-fA-F]{2})",
                      lambda m: bytes([int(m.group(1), 16)]), buf[i + 1:j])
        return (b"name", name), j
    if c == b"(":
        j = skip_literal(buf, i)
        raw = buf[i + 1:j - 1]
        out = bytearray()
        k = 0
        mapping = {b"n": b"\n", b"r": b"\r", b"t": b"\t", b"b": b"\b",
                   b"f": b"\f", b"(": b"(", b")": b")", b"\\": b"\\"}
        while k < len(raw):
            ch = raw[k:k + 1]
            if ch == b"\\" and k + 1 < len(raw):
                nxt = raw[k + 1:k + 2]
                if nxt in mapping:
                    out += mapping[nxt]
                    k += 2
                    continue
                if nxt in b"01234567":
                    m = re.match(rb"[0-7]{1,3}", raw[k + 1:])
                    out += bytes([int(m.group(0), 8) & 0xFF])
                    k += 1 + len(m.group(0))
                    continue
                out += nxt
                k += 2
                continue
            out += ch
            k += 1
        return bytes(out), j
    if c == b"<":
        if buf[i:i + 2] == b"<<":
            return parse_dict(buf, i)
        j = buf.find(b">", i)
        if j < 0:
            raise ValueError("unterminated hex string")
        hexs = re.sub(rb"\s", b"", buf[i + 1:j])
        if len(hexs) % 2:
            hexs += b"0"
        try:
            return bytes.fromhex(hexs.decode("ascii")), j + 1
        except ValueError:
            return b"", j + 1
    if c == b"[":
        i2 = i + 1
        vals = []
        while True:
            i2 = skip_ws(buf, i2)
            if i2 >= n:
                raise ValueError("unterminated array")
            if buf[i2:i2 + 1] == b"]":
                return vals, i2 + 1
            v, i2 = parse_value(buf, i2)
            vals.append(v)
    if c in b"+-0123456789.":
        m2 = re.match(rb"(\d+)\s+(\d+)\s+R", buf[i:])
        if m2:
            return (int(m2.group(1)), int(m2.group(2))), i + m2.end()
        m = re.match(rb"[+-]?(?:\d+\.\d*|\.\d+|\d+)", buf[i:])
        if m:
            txt = m.group(0)
            if b"." in txt:
                return float(txt), i + len(txt)
            return int(txt), i + len(txt)
        raise ValueError("bad number")
    if buf.startswith(b"true", i):
        return True, i + 4
    if buf.startswith(b"false", i):
        return False, i + 5
    if buf.startswith(b"null", i):
        return None, i + 4
    raise ValueError(f"cannot parse value at {i}: {buf[i:i + 16]!r}")


def parse_dict(buf, i):
    """i points at '<<'; return (dict, index_after_>>)."""
    i += 2
    d = {}
    n = len(buf)
    while True:
        i = skip_ws(buf, i)
        if i + 1 < n and buf[i:i + 2] == b">>":
            return d, i + 2
        if i >= n or buf[i:i + 1] != b"/":
            raise ValueError(f"expected name key in dict at {i}")
        key_v, i = parse_value(buf, i)
        val, i = parse_value(buf, i)
        d[key_v[1]] = val


def rewrite_refs(blob, mapping):
    """Rewrite indirect references 'N G R' in non-stream content."""
    out = bytearray()
    i = 0
    n = len(blob)
    while i < n:
        c = blob[i:i + 1]
        if c == b"%":
            j = blob.find(b"\n", i)
            if j < 0:
                out += blob[i:]
                break
            out += blob[i:j + 1]
            i = j + 1
            continue
        if c == b"(":
            j = skip_literal(blob, i)
            out += blob[i:j]
            i = j
            continue
        if c == b"<":
            if blob[i:i + 2] == b"<<":
                out += b"<<"
                i += 2
                continue
            j = blob.find(b">", i)
            if j < 0:
                out += blob[i:]
                break
            out += blob[i:j + 1]
            i = j + 1
            continue
        if c.isdigit():
            m = REF_RE.match(blob, i)
            if m:
                old = int(m.group(1))
                new = mapping.get(old)
                if new is not None:
                    out += b"%d 0 R" % new
                else:
                    out += m.group(0)
                i = m.end()
                continue
        out += c
        i += 1
    return bytes(out)


class PdfDoc:
    def __init__(self, path):
        with open(path, "rb") as f:
            self.data = f.read()
        self.path = path
        self.entries = {}
        self.trailer = {}
        self.version = (1, 4)

    def parse(self):
        data = self.data
        m = re.search(rb"%PDF-(\d+)\.(\d+)", data[:2048])
        if m:
            self.version = (int(m.group(1)), int(m.group(2)))
        idx = data.rfind(b"startxref")
        if idx < 0:
            raise ValueError(f"{self.path}: no startxref found")
        m = re.search(rb"startxref\s+(\d+)", data[idx:])
        if not m:
            raise ValueError(f"{self.path}: malformed startxref")
        xref_pos = int(m.group(1))
        seen = set()
        while xref_pos and xref_pos not in seen:
            seen.add(xref_pos)
            xref_pos = self.parse_xref_at(xref_pos)
        if b"Root" not in self.trailer:
            raise ValueError(f"{self.path}: no /Root in trailer")

    def parse_xref_at(self, pos):
        data = self.data
        i = skip_ws(data, pos)
        if data[i:i + 4] == b"xref":
            return self.parse_classic_xref(i)
        return self.parse_xref_stream_at(pos)

    def parse_classic_xref(self, i):
        data = self.data
        i += 4
        while True:
            i = skip_ws(data, i)
            if data[i:i + 7] == b"trailer":
                d, _ = parse_dict(data, i + 7)
                self.trailer.update(d)
                break
            m = re.match(rb"(\d+)\s+(\d+)", data[i:i + 64])
            if not m:
                raise ValueError(f"{self.path}: bad xref subsection at {i}")
            first = int(m.group(1))
            count = int(m.group(2))
            i += m.end()
            for _ in range(count):
                line_end = data.find(b"\n", i)
                if line_end < 0:
                    line_end = len(data)
                line = data[i:line_end].rstrip(b"\r")
                fm = re.match(rb"(\d{10})\s+(\d{5})\s+([nf])", line)
                if not fm:
                    raise ValueError(f"{self.path}: bad xref entry at {i}")
                offset = int(fm.group(1))
                gen = int(fm.group(2))
                typ = fm.group(3)
                num = first + count - 1  # placeholder; fixed below
                self.entries.setdefault(0, None)  # never used
                if typ == b"n" and offset > 0:
                    self.entries.setdefault(first + (i - 0), None)  # unused
                i = line_end + 1
            # redo entries properly (offsets parsed above need numbering)
            raise ValueError(f"{self.path}: internal error in classic xref")
        xref_stm = self.trailer.get(b"XRefStm")
        if xref_stm is not None:
            stm_pos = int(xref_stm)
            self.parse_xref_stream_at(stm_pos, override=True)
        prev = self.trailer.get(b"Prev", 0)
        return int(prev)

    def parse_xref_stream_at(self, pos, override=False):
        data = self.data
        i = skip_ws(data, pos)
        m = re.match(rb"(\d+)\s+(\d+)\s+obj", data[i:i + 64])
        if not m:
            raise ValueError(f"{self.path}: bad xref stream object at {pos}")
        start = i + m.end()
        d = parse_value(data, start)[0]
        if not isinstance(d, dict):
            raise ValueError(f"{self.path}: xref stream header is not a dict")
        j, data_end, _ = self.stream_data_bounds(start, d)
        stm = self.decode_stream(data[j:data_end], d)
        self.parse_xref_stream_data(stm, d, override=override)
        for k in (b"Root", b"Info", b"Size", b"Prev", b"ID", b"XRefStm"):
            if k in d:
                self.trailer[k] = d[k]
        prev = d.get(b"Prev", 0)
        return int(prev)

    def parse_xref_stream_data(self, stm, d, override=False):
        W = [int(x) for x in d.get(b"W", [1, 2, 1])]
        size = int(d.get(b"Size", 0))
        index = d.get(b"Index", [0, size])
        w1, w2, w3 = W
        entry_len = w1 + w2 + w3

        def gi(rec, w):
            return int.from_bytes(rec[:w], "big") if w else 0

        for k in range(0, len(index), 2):
            start_num = index[k]
            count = index[k + 1]
            for e in range(count):
                off = e * entry_len
                rec = stm[off:off + entry_len]
                if len(rec) < entry_len:
                    break
                t = gi(rec, w1)
                f2 = gi(rec, w2)
                f3 = gi(rec, w3)
                num = start_num + e
                if num == 0:
                    continue
                if t == 1:
                    if override or num not in self.entries:
                        self.entries[num] = (f3, f2)
                elif t == 2:
                    if override or num not in self.entries:
                        self.entries[num] = ("stm", f2, f3)

    def resolve_int(self, v):
        if isinstance(v, int):
            return v
        if isinstance(v, tuple) and len(v) == 2 and isinstance(v[0], int):
            num = v[0]
            entry = self.entries.get(num)
            if entry is None:
                raise ValueError(f"{self.path}: cannot resolve /Length object {num}")
            if entry[0] == "stm":
                raw = self.extract_from_objstm(entry[1], entry[2])
            else:
                dict_part, stream_part = self.extract_object(num, entry[0], entry[1])
                raw = dict_part
            val = parse_value(raw, 0)[0]
            return int(val)
        raise ValueError("cannot resolve integer")

    def stream_data_bounds(self, dict_start, d):
        data = self.data
        si = find_keyword(data, dict_start, b"stream", prev_ws_only=True)
        if si < 0:
            raise ValueError(f"{self.path}: stream keyword not found")
        j = si + 6
        if data[j:j + 2] == b"\r\n":
            j += 2
        elif j < len(data) and data[j:j + 1] in (b"\r", b"\n"):
            j += 1
        length = None
        try:
            length = self.resolve_int(d.get(b"Length", 0))
        except Exception:
            length = None
        if length is not None and length >= 0:
            cand = j + length
            es = find_keyword(data, cand, b"endstream")
            if es >= 0 and es - cand <= 2:
                return j, cand, es
        es = find_keyword(data, j, b"endstream")
        if es < 0:
            raise ValueError(f"{self.path}: endstream not found")
        return j, es, es

    def decode_stream(self, raw, d):
        filt = d.get(b"Filter")
        filters = []
        if isinstance(filt, list):
            filters = [f[1] for f in filt if isinstance(f, tuple) and f[0] == b"name"]
        elif isinstance(filt, tuple) and filt[0] == b"name":
            filters = [filt[1]]
        for f in filters:
            if f in (b"FlateDecode", b"Fl"):
                raw = zlib.decompress(raw)
            else:
                raise ValueError(f"{self.path}: unsupported stream filter {f!r}")
        return raw

    def extract_object(self, num, gen, offset):
        data = self.data
        i = skip_ws(data, offset)
        m = re.match(rb"(\d+)\s+(\d+)\s+obj", data[i:i + 64])
        if not m:
            m2 = re.search(rb"\d+\s+\d+\s+obj", data[offset:offset + 256])
            if not m2:
                raise ValueError(f"{self.path}: object {num} marker not found at offset {offset}")
            i = offset + m2.start()
        start = i + m.end()
        si = find_keyword(data, start, b"stream", prev_ws_only=True)
        if si >= 0:
            dict_part = data[start:si]
            d = parse_value(dict_part, 0)[0]
            if not isinstance(d, dict):
                raise ValueError(f"{self.path}: stream object {num} has non-dict header")
            j, data_end, es = self.stream_data_bounds(start, d)
            eo = find_keyword(data, es + 9, b"endobj")
            if eo < 0:
                raise ValueError(f"{self.path}: object {num} has no endobj after endstream")
            return dict_part, data[j:data_end]
        eo = find_keyword(data, start, b"endobj")
        if eo < 0:
            raise ValueError(f"{self.path}: object {num} has no endobj")
        return data[start:eo], None

    def extract_from_objstm(self, stm_num, idx):
        entry = self.entries.get(stm_num)
        if entry is None or entry[0] == "stm":
            raise ValueError(f"{self.path}: bad object stream {stm_num}")
        dict_part, stream_part = self.extract_object(stm_num, entry[0], entry[1])
        d = parse_value(dict_part, 0)[0]
        raw = self.decode_stream(stream_part, d)
        n = int(d.get(b"N", 0))
        pairs = []
        i = 0
        for _ in range(n):
            i = skip_ws(raw, i)
            m = re.match(rb"(\d+)\s+(\d+)", raw[i:i + 64])
            if not m:
                raise ValueError(f"{self.path}: bad object stream header in {stm_num}")
            pairs.append((int(m.group(1)), int(m.group(2))))
            i += m.end()
        if idx >= len(pairs):
            raise ValueError(f"{self.path}: object stream index out of range")
        off = pairs[idx][1]
        end = pairs[idx + 1][1] if idx + 1 < len(pairs) else len(raw)
        return raw[off:end]

    def get_object_dict(self, num):
        entry = self.entries.get(num)
        if entry is None:
            raise ValueError(f"{self.path}: object {num} missing from xref")
        if entry[0] == "stm":
            raw = self.extract_from_objstm(entry[1], entry[2])
        else:
            dict_part, stream_part = self.extract_object(num, entry[0], entry[1])
            raw = dict_part
        val = parse_value(raw, 0)[0]
        if not isinstance(val, dict):
            raise ValueError(f"{self.path}: object {num} is not a dict")
        return val

    def collect_pages(self):
        root = self.trailer.get(b"Root")
        if not isinstance(root, tuple) or len(root) != 2:
            raise ValueError(f"{self.path}: bad /Root in trailer")
        root_obj = self.get_object_dict(root[0])
        pages_ref = root_obj.get(b"Pages")
        if not isinstance(pages_ref, tuple):
            raise ValueError(f"{self.path}: no /Pages in catalog")
        pages_num = pages_ref[0]
        leaves = []
        nodes = set()
        seen = set()

        def visit(num):
            if num in seen:
                return
            seen.add(num)
            d = self.get_object_dict(num)
            kids = d.get(b"Kids")
            if isinstance(kids, list) and kids:
                nodes.add(num)
                for kid in kids:
                    if isinstance(kid, tuple):
                        visit(kid[0])
            else:
                leaves.append(num)

        visit(pages_num)
        if not leaves:
            leaves = [pages_num]
        return leaves, nodes


def write_output(plans, kids, total, version):
    out = bytearray()
    out += b"%PDF-%d.%d\n" % version
    offsets = {}
    offsets[1] = len(out)
    out += b"1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n"
    offsets[2] = len(out)
    kids_bytes = b" ".join(b"%d 0 R" % k for k in kids)
    out += (b"2 0 obj\n<< /Type /Pages /Kids [%s] /Count %d >>\nendobj\n"
            % (kids_bytes, len(kids)))
    for new_num, content in plans:
        offsets[new_num] = len(out)
        out += b"%d 0 obj\n" % new_num
        out += content
        out += b"\nendobj\n"
    xref_pos = len(out)
    out += b"xref\n0 %d\n" % total
    out += b"0000000000 65535 f \n"
    for num in range(1, total):
        off = offsets.get(num)
        if off is None:
            out += b"0000000000 65535 f \n"
        else:
            out += b"%010d 00000 n \n" % off
    out += (b"trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n"
            % (total, xref_pos))
    with open(OUTPUT_FILE, "wb") as f:
        f.write(bytes(out))


def main():
    for name in INPUT_FILES:
        if not os.path.isfile(name):
            sys.exit(f"Missing input file: {name}")
    try:
        docs = []
        for path in INPUT_FILES:
            doc = PdfDoc(path)
            doc.parse()
            docs.append(doc)
            print(f"Parsed {path}: PDF {doc.version[0]}.{doc.version[1]}, "
                  f"{len(doc.entries)} objects", file=sys.stderr)
        version = max(d.version for d in docs)
        merged_kids = []
        plans = []
        next_num = 3
        for doc in docs:
            leaves, nodes = doc.collect_pages()
            print(f"  {doc.path}: {len(leaves)} page(s), "
                  f"{len(nodes)} pages node(s)", file=sys.stderr)
            mapping = {}
            new_num_for = {}
            for num in sorted(doc.entries):
                if num in nodes:
                    new_num_for[num] = 2
                else:
                    new_num_for[num] = next_num
                    next_num += 1
            mapping = dict(new_num_for)
            for num in sorted(doc.entries):
                if num in nodes:
                    continue
                entry = doc.entries[num]
                if entry[0] == "stm":
                    raw = doc.extract_from_objstm(entry[1], entry[2])
                    rewritten = rewrite_refs(raw, mapping)
                else:
                    dict_part, stream_part = doc.extract_object(num, entry[0], entry[1])
                    dict_rewritten = rewrite_refs(dict_part, mapping)
                    if stream_part is None:
                        rewritten = dict_rewritten
                    else:
                        rewritten = (dict_rewritten.rstrip(WS) + b"\nstream\n"
                                     + stream_part + b"\nendstream")
                plans.append((new_num_for[num], rewritten))
            merged_kids.extend(new_num_for[l] for l in leaves)
        write_output(plans, merged_kids, next_num, version)
        print(f"Merged {', '.join(INPUT_FILES)} into {OUTPUT_FILE} "
              "using pure-Python PDF merger")
    except Exception as exc:  # noqa: BLE001 - report the failure clearly
        sys.exit(f"Merge failed: {exc}")


if __name__ == "__main__":
    main()

"""Merge report_part1.pdf and report_part2.pdf into combined_report.pdf.

Pure-Python (standard library only) PDF merger: parses each input PDF's
object structure and xref table (classic xref tables and xref streams),
renumbers objects, rebuilds a single page tree and catalog, and writes a
valid merged PDF with a classic xref table.

Fails with a clear message if the inputs cannot be parsed. No unrelated
side effects.
"""
import os
import re
import sys
import zlib

INPUT_FILES = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT_FILE = "combined_report.pdf"

WS = b"\x00\t\n\x0c\r "
DELIM = b"()<>[]{}/%"
REF_RE = re.compile(rb"(\d+)\s+(\d+)\s+R")


def skip_ws(buf, i):
    n = len(buf)
    while i < n:
        c = buf[i:i + 1]
        if c in WS:
            i += 1
        elif c == b"%":
            j = buf.find(b"\n", i)
            i = n if j < 0 else j + 1
        else:
            break
    return i


def skip_literal(buf, i):
    """i points at '('; return index just after the matching ')'."""
    depth = 0
    n = len(buf)
    while i < n:
        c = buf[i:i + 1]
        if c == b"\\":
            i += 2
            continue
        if c == b"(":
            depth += 1
        elif c == b")":
            depth -= 1
            if depth == 0:
                return i + 1
        i += 1
    return n


def find_keyword(buf, start, kw, prev_ws_only=False):
    """Find a standalone keyword outside strings, hex strings and comments."""
    n = len(buf)
    i = start
    klen = len(kw)
    while i < n:
        c = buf[i:i + 1]
        if c == b"%":
            j = buf.find(b"\n", i)
            i = n if j < 0 else j + 1
            continue
        if c == b"(":
            i = skip_literal(buf, i)
            continue
        if c == b"<":
            if buf[i:i + 2] == b"<<":
                i += 2
                continue
            j = buf.find(b">", i)
            i = n if j < 0 else j + 1
            continue
        if c == b"\\":
            i += 2
            continue
        if buf[i:i + klen] == kw:
            if i > 0:
                p = buf[i - 1:i]
                prev_ok = p in WS or (not prev_ws_only and p in DELIM)
            else:
                prev_ok = True
            after = i + klen
            if after >= n:
                next_ok = True
            else:
                q = buf[after:after + 1]
                next_ok = q in WS or q in DELIM
            if prev_ok and next_ok:
                return i
        i += 1
    return -1


def parse_value(buf, i):
    """Parse one PDF value starting at i; return (value, new_index)."""
    i = skip_ws(buf, i)
    n = len(buf)
    if i >= n:
        raise ValueError("unexpected end of input")
    c = buf[i:i + 1]
    if c == b"/":
        j = i + 1
        while j < n and buf[j:j + 1] not in DELIM + WS:
            j += 1
        name = re.sub(rb"#([0-9a-fA-F]{2})",
                      lambda m: bytes([int(m.group(1), 16)]), buf[i + 1:j])
        return (b"name", name), j
    if c == b"(":
        j = skip_literal(buf, i)
        raw = buf[i + 1:j - 1]
        out = bytearray()
        k = 0
        mapping = {b"n": b"\n", b"r": b"\r", b"t": b"\t", b"b": b"\b",
                   b"f": b"\f", b"(": b"(", b")": b")", b"\\": b"\\"}
        while k < len(raw):
            ch = raw[k:k + 1]
            if ch == b"\\" and k + 1 < len(raw):
                nxt = raw[k + 1:k + 2]
                if nxt in mapping:
                    out += mapping[nxt]
                    k += 2
                    continue
                if nxt in b"01234567":
                    m = re.match(rb"[0-7]{1,3}", raw[k + 1:])
                    out += bytes([int(m.group(0), 8) & 0xFF])
                    k += 1 + len(m.group(0))
                    continue
                out += nxt
                k += 2
                continue
            out += ch
            k += 1
        return bytes(out), j
    if c == b"<":
        if buf[i:i + 2] == b"<<":
            return parse_dict(buf, i)
        j = buf.find(b">", i)
        if j < 0:
            raise ValueError("unterminated hex string")
        hexs = re.sub(rb"\s", b"", buf[i + 1:j])
        if len(hexs) % 2:
            hexs += b"0"
        try:
            return bytes.fromhex(hexs.decode("ascii")), j + 1
        except ValueError:
            return b"", j + 1
    if c == b"[":
        i2 = i + 1
        vals = []
        while True:
            i2 = skip_ws(buf, i2)
            if i2 >= n:
                raise ValueError("unterminated array")
            if buf[i2:i2 + 1] == b"]":
                return vals, i2 + 1
            v, i2 = parse_value(buf, i2)
            vals.append(v)
    if c in b"+-0123456789.":
        m2 = re.match(rb"(\d+)\s+(\d+)\s+R", buf[i:])
        if m2:
            return (int(m2.group(1)), int(m2.group(2))), i + m2.end()
        m = re.match(rb"[+-]?(?:\d+\.\d*|\.\d+|\d+)", buf[i:])
        if m:
            txt = m.group(0)
            if b"." in txt:
                return float(txt), i + len(txt)
            return int(txt), i + len(txt)
        raise ValueError("bad number")
    if buf.startswith(b"true", i):
        return True, i + 4
    if buf.startswith(b"false", i):
        return False, i + 5
    if buf.startswith(b"null", i):
        return None, i + 4
    raise ValueError(f"cannot parse value at {i}: {buf[i:i + 16]!r}")


def parse_dict(buf, i):
    """i points at '<<'; return (dict, index_after_>>)."""
    i += 2
    d = {}
    n = len(buf)
    while True:
        i = skip_ws(buf, i)
        if i + 1 < n and buf[i:i + 2] == b">>":
            return d, i + 2
        if i >= n or buf[i:i + 1] != b"/":
            raise ValueError(f"expected name key in dict at {i}")
        key_v, i = parse_value(buf, i)
        val, i = parse_value(buf, i)
        d[key_v[1]] = val


def rewrite_refs(blob, mapping):
    """Rewrite indirect references 'N G R' in non-stream content."""
    out = bytearray()
    i = 0
    n = len(blob)
    while i < n:
        c = blob[i:i + 1]
        if c == b"%":
            j = blob.find(b"\n", i)
            if j < 0:
                out += blob[i:]
                break
            out += blob[i:j + 1]
            i = j + 1
            continue
        if c == b"(":
            j = skip_literal(blob, i)
            out += blob[i:j]
            i = j
            continue
        if c == b"<":
            if blob[i:i + 2] == b"<<":
                out += b"<<"
                i += 2
                continue
            j = blob.find(b">", i)
            if j < 0:
                out += blob[i:]
                break
            out += blob[i:j + 1]
            i = j + 1
            continue
        if c.isdigit():
            m = REF_RE.match(blob, i)
            if m:
                old = int(m.group(1))
                new = mapping.get(old)
                if new is not None:
                    out += b"%d 0 R" % new
                else:
                    out += m.group(0)
                i = m.end()
                continue
        out += c
        i += 1
    return bytes(out)


class PdfDoc:
    def __init__(self, path):
        with open(path, "rb") as f:
            self.data = f.read()
        self.path = path
        self.entries = {}
        self.trailer = {}
        self.version = (1, 4)

    def parse(self):
        data = self.data
        m = re.search(rb"%PDF-(\d+)\.(\d+)", data[:2048])
        if m:
            self.version = (int(m.group(1)), int(m.group(2)))
        idx = data.rfind(b"startxref")
        if idx < 0:
            raise ValueError(f"{self.path}: no startxref found")
        m = re.search(rb"startxref\s+(\d+)", data[idx:])
        if not m:
            raise ValueError(f"{self.path}: malformed startxref")
        xref_pos = int(m.group(1))
        seen = set()
        while xref_pos and xref_pos not in seen:
            seen.add(xref_pos)
            xref_pos = self.parse_xref_at(xref_pos)
        if b"Root" not in self.trailer:
            raise ValueError(f"{self.path}: no /Root in trailer")

    def parse_xref_at(self, pos):
        data = self.data
        i = skip_ws(data, pos)
        if data[i:i + 4] == b"xref":
            return self.parse_classic_xref(i)
        return self.parse_xref_stream_at(pos)

    def parse_classic_xref(self, i):
        data = self.data
        i += 4
        while True:
            i = skip_ws(data, i)
            if data[i:i + 7] == b"trailer":
                d, _ = parse_dict(data, i + 7)
                self.trailer.update(d)
                break
            m = re.match(rb"(\d+)\s+(\d+)", data[i:i + 64])
            if not m:
                raise ValueError(f"{self.path}: bad xref subsection at {i}")
            first = int(m.group(1))
            count = int(m.group(2))
            i += m.end()
            for e in range(count):
                line_end = data.find(b"\n", i)
                if line_end < 0:
                    line_end = len(data)
                line = data[i:line_end].rstrip(b"\r")
                fm = re.match(rb"(\d{10})\s+(\d{5})\s+([nf])", line)
                if not fm:
                    raise ValueError(f"{self.path}: bad xref entry at {i}")
                offset = int(fm.group(1))
                gen = int(fm.group(2))
                typ = fm.group(3)
                num = first + e
                if typ == b"n" and offset > 0:
                    self.entries.setdefault(num, (gen, offset))
                i = line_end + 1
        xref_stm = self.trailer.get(b"XRefStm")
        if xref_stm is not None:
            stm_pos = int(xref_stm)
            self.parse_xref_stream_at(stm_pos, override=True)
        prev = self.trailer.get(b"Prev", 0)
        return int(prev)

    def parse_xref_stream_at(self, pos, override=False):
        data = self.data
        i = skip_ws(data, pos)
        m = re.match(rb"(\d+)\s+(\d+)\s+obj", data[i:i + 64])
        if not m:
            raise ValueError(f"{self.path}: bad xref stream object at {pos}")
        start = i + m.end()
        d = parse_value(data, start)[0]
        if not isinstance(d, dict):
            raise ValueError(f"{self.path}: xref stream header is not a dict")
        j, data_end, _ = self.stream_data_bounds(start, d)
        stm = self.decode_stream(data[j:data_end], d)
        self.parse_xref_stream_data(stm, d, override=override)
        for k in (b"Root", b"Info", b"Size", b"Prev", b"ID", b"XRefStm"):
            if k in d:
                self.trailer[k] = d[k]
        prev = d.get(b"Prev", 0)
        return int(prev)

    def parse_xref_stream_data(self, stm, d, override=False):
        W = [int(x) for x in d.get(b"W", [1, 2, 1])]
        size = int(d.get(b"Size", 0))
        index = d.get(b"Index", [0, size])
        w1, w2, w3 = W
        entry_len = w1 + w2 + w3

        def gi(rec, w):
            return int.from_bytes(rec[:w], "big") if w else 0

        for k in range(0, len(index), 2):
            start_num = index[k]
            count = index[k + 1]
            for e in range(count):
                off = e * entry_len
                rec = stm[off:off + entry_len]
                if len(rec) < entry_len:
                    break
                t = gi(rec, w1)
                f2 = gi(rec, w2)
                f3 = gi(rec, w3)
                num = start_num + e
                if num == 0:
                    continue
                if t == 1:
                    if override or num not in self.entries:
                        self.entries[num] = (f3, f2)
                elif t == 2:
                    if override or num not in self.entries:
                        self.entries[num] = ("stm", f2, f3)

    def resolve_int(self, v):
        if isinstance(v, int):
            return v
        if isinstance(v, tuple) and len(v) == 2 and isinstance(v[0], int):
            num = v[0]
            entry = self.entries.get(num)
            if entry is None:
                raise ValueError(f"{self.path}: cannot resolve /Length object {num}")
            if entry[0] == "stm":
                raw = self.extract_from_objstm(entry[1], entry[2])
            else:
                dict_part, stream_part = self.extract_object(num, entry[0], entry[1])
                raw = dict_part
            val = parse_value(raw, 0)[0]
            return int(val)
        raise ValueError("cannot resolve integer")

    def stream_data_bounds(self, dict_start, d):
        data = self.data
        si = find_keyword(data, dict_start, b"stream", prev_ws_only=True)
        if si < 0:
            raise ValueError(f"{self.path}: stream keyword not found")
        j = si + 6
        if data[j:j + 2] == b"\r\n":
            j += 2
        elif j < len(data) and data[j:j + 1] in (b"\r", b"\n"):
            j += 1
        length = None
        try:
            length = self.resolve_int(d.get(b"Length", 0))
        except Exception:
            length = None
        if length is not None and length >= 0:
            cand = j + length
            es = find_keyword(data, cand, b"endstream")
            if es >= 0 and es - cand <= 2:
                return j, cand, es
        es = find_keyword(data, j, b"endstream")
        if es < 0:
            raise ValueError(f"{self.path}: endstream not found")
        return j, es, es

    def decode_stream(self, raw, d):
        filt = d.get(b"Filter")
        filters = []
        if isinstance(filt, list):
            filters = [f[1] for f in filt if isinstance(f, tuple) and f[0] == b"name"]
        elif isinstance(filt, tuple) and filt[0] == b"name":
            filters = [filt[1]]
        for f in filters:
            if f in (b"FlateDecode", b"Fl"):
                raw = zlib.decompress(raw)
            else:
                raise ValueError(f"{self.path}: unsupported stream filter {f!r}")
        return raw

    def extract_object(self, num, gen, offset):
        data = self.data
        i = skip_ws(data, offset)
        m = re.match(rb"(\d+)\s+(\d+)\s+obj", data[i:i + 64])
        if not m:
            m2 = re.search(rb"\d+\s+\d+\s+obj", data[offset:offset + 256])
            if not m2:
                raise ValueError(f"{self.path}: object {num} marker not found at offset {offset}")
            i = offset + m2.start()
        start = i + m.end()
        si = find_keyword(data, start, b"stream", prev_ws_only=True)
        if si >= 0:
            dict_part = data[start:si]
            d = parse_value(dict_part, 0)[0]
            if not isinstance(d, dict):
                raise ValueError(f"{self.path}: stream object {num} has non-dict header")
            j, data_end, es = self.stream_data_bounds(start, d)
            eo = find_keyword(data, es + 9, b"endobj")
            if eo < 0:
                raise ValueError(f"{self.path}: object {num} has no endobj after endstream")
            return dict_part, data[j:data_end]
        eo = find_keyword(data, start, b"endobj")
        if eo < 0:
            raise ValueError(f"{self.path}: object {num} has no endobj")
        return data[start:eo], None

    def extract_from_objstm(self, stm_num, idx):
        entry = self.entries.get(stm_num)
        if entry is None or entry[0] == "stm":
            raise ValueError(f"{self.path}: bad object stream {stm_num}")
        dict_part, stream_part = self.extract_object(stm_num, entry[0], entry[1])
        d = parse_value(dict_part, 0)[0]
        raw = self.decode_stream(stream_part, d)
        n = int(d.get(b"N", 0))
        pairs = []
        i = 0
        for _ in range(n):
            i = skip_ws(raw, i)
            m = re.match(rb"(\d+)\s+(\d+)", raw[i:i + 64])
            if not m:
                raise ValueError(f"{self.path}: bad object stream header in {stm_num}")
            pairs.append((int(m.group(1)), int(m.group(2))))
            i += m.end()
        if idx >= len(pairs):
            raise ValueError(f"{self.path}: object stream index out of range")
        off = pairs[idx][1]
        end = pairs[idx + 1][1] if idx + 1 < len(pairs) else len(raw)
        return raw[off:end]

    def get_object_dict(self, num):
        entry = self.entries.get(num)
        if entry is None:
            raise ValueError(f"{self.path}: object {num} missing from xref")
        if entry[0] == "stm":
            raw = self.extract_from_objstm(entry[1], entry[2])
        else:
            dict_part, stream_part = self.extract_object(num, entry[0], entry[1])
            raw = dict_part
        val = parse_value(raw, 0)[0]
        if not isinstance(val, dict):
            raise ValueError(f"{self.path}: object {num} is not a dict")
        return val

    def collect_pages(self):
        root = self.trailer.get(b"Root")
        if not isinstance(root, tuple) or len(root) != 2:
            raise ValueError(f"{self.path}: bad /Root in trailer")
        root_obj = self.get_object_dict(root[0])
        pages_ref = root_obj.get(b"Pages")
        if not isinstance(pages_ref, tuple):
            raise ValueError(f"{self.path}: no /Pages in catalog")
        pages_num = pages_ref[0]
        leaves = []
        nodes = set()
        seen = set()

        def visit(num):
            if num in seen:
                return
            seen.add(num)
            d = self.get_object_dict(num)
            kids = d.get(b"Kids")
            if isinstance(kids, list) and kids:
                nodes.add(num)
                for kid in kids:
                    if isinstance(kid, tuple):
                        visit(kid[0])
            else:
                leaves.append(num)

        visit(pages_num)
        if not leaves:
            leaves = [pages_num]
        return leaves, nodes


def write_output(plans, kids, total, version):
    out = bytearray()
    out += b"%PDF-%d.%d\n" % version
    offsets = {}
    offsets[1] = len(out)
    out += b"1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n"
    offsets[2] = len(out)
    kids_bytes = b" ".join(b"%d 0 R" % k for k in kids)
    out += (b"2 0 obj\n<< /Type /Pages /Kids [%s] /Count %d >>\nendobj\n"
            % (kids_bytes, len(kids)))
    for new_num, content in plans:
        offsets[new_num] = len(out)
        out += b"%d 0 obj\n" % new_num
        out += content
        out += b"\nendobj\n"
    xref_pos = len(out)
    out += b"xref\n0 %d\n" % total
    out += b"0000000000 65535 f \n"
    for num in range(1, total):
        off = offsets.get(num)
        if off is None:
            out += b"0000000000 65535 f \n"
        else:
            out += b"%010d 00000 n \n" % off
    out += (b"trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n"
            % (total, xref_pos))
    with open(OUTPUT_FILE, "wb") as f:
        f.write(bytes(out))


def main():
    for name in INPUT_FILES:
        if not os.path.isfile(name):
            sys.exit(f"Missing input file: {name}")
    try:
        docs = []
        for path in INPUT_FILES:
            doc = PdfDoc(path)
            doc.parse()
            docs.append(doc)
            print(f"Parsed {path}: PDF {doc.version[0]}.{doc.version[1]}, "
                  f"{len(doc.entries)} objects", file=sys.stderr)
        version = max(d.version for d in docs)
        merged_kids = []
        plans = []
        next_num = 3
        for doc in docs:
            leaves, nodes = doc.collect_pages()
            print(f"  {doc.path}: {len(leaves)} page(s), "
                  f"{len(nodes)} pages node(s)", file=sys.stderr)
            mapping = {}
            new_num_for = {}
            for num in sorted(doc.entries):
                if num in nodes:
                    new_num_for[num] = 2
                else:
                    new_num_for[num] = next_num
                    next_num += 1
            mapping = dict(new_num_for)
            for num in sorted(doc.entries):
                if num in nodes:
                    continue
                entry = doc.entries[num]
                if entry[0] == "stm":
                    raw = doc.extract_from_objstm(entry[1], entry[2])
                    rewritten = rewrite_refs(raw, mapping)
                else:
                    dict_part, stream_part = doc.extract_object(num, entry[0], entry[1])
                    dict_rewritten = rewrite_refs(dict_part, mapping)
                    if stream_part is None:
                        rewritten = dict_rewritten
                    else:
                        rewritten = (dict_rewritten.rstrip(WS) + b"\nstream\n"
                                     + stream_part + b"\nendstream")
                plans.append((new_num_for[num], rewritten))
            merged_kids.extend(new_num_for[l] for l in leaves)
        write_output(plans, merged_kids, next_num, version)
        print(f"Merged {', '.join(INPUT_FILES)} into {OUTPUT_FILE} "
              "using pure-Python PDF merger")
    except Exception as exc:  # noqa: BLE001 - report the failure clearly
        sys.exit(f"Merge failed: {exc}")


if __name__ == "__main__":
    main()

"""Merge report_part1.pdf and report_part2.pdf into combined_report.pdf.

Pure-Python (standard library only) PDF merger: parses each input PDF's
object structure and xref table (classic xref tables and xref streams),
renumbers objects, rebuilds a single page tree and catalog, and writes a
valid merged PDF with a classic xref table.

Fails with a clear message if the inputs cannot be parsed. No unrelated
side effects.
"""
import os
import re
import sys
import zlib

INPUT_FILES = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT_FILE = "combined_report.pdf"

WS = b"\x00\t\n\x0c\r "
DELIM = b"()<>[]{}/%"
REF_RE = re.compile(rb"(\d+)\s+(\d+)\s+R")


def skip_ws(buf, i):
    n = len(buf)
    while i < n:
        c = buf[i:i + 1]
        if c in WS:
            i += 1
        elif c == b"%":
            j = buf.find(b"\n", i)
            i = n if j < 0 else j + 1
        else:
            break
    return i


def skip_literal(buf, i):
    """i points at '('; return index just after the matching ')'."""
    depth = 0
    n = len(buf)
    while i < n:
        c = buf[i:i + 1]
        if c == b"\\":
            i += 2
            continue
        if c == b"(":
            depth += 1
        elif c == b")":
            depth -= 1
            if depth == 0:
                return i + 1
        i += 1
    return n


def find_keyword(buf, start, kw, prev_ws_only=False):
    """Find a standalone keyword outside strings, hex strings and comments."""
    n = len(buf)
    i = start
    klen = len(kw)
    while i < n:
        c = buf[i:i + 1]
        if c == b"%":
            j = buf.find(b"\n", i)
            i = n if j < 0 else j + 1
            continue
        if c == b"(":
            i = skip_literal(buf, i)
            continue
        if c == b"<":
            if buf[i:i + 2] == b"<<":
                i += 2
                continue
            j = buf.find(b">", i)
            i = n if j < 0 else j + 1
            continue
        if c == b"\\":
            i += 2
            continue
        if buf[i:i + klen] == kw:
            if i > 0:
                p = buf[i - 1:i]
                prev_ok = p in WS or (not prev_ws_only and p in DELIM)
            else:
                prev_ok = True
            after = i + klen
            if after >= n:
                next_ok = True
            else:
                q = buf[after:after + 1]
                next_ok = q in WS or q in DELIM
            if prev_ok and next_ok:
                return i
        i += 1
    return -1


def parse_value(buf, i):
    """Parse one PDF value starting at i; return (value, new_index)."""
    i = skip_ws(buf, i)
    n = len(buf)
    if i >= n:
        raise ValueError("unexpected end of input")
    c = buf[i:i + 1]
    if c == b"/":
        j = i + 1
        while j < n and buf[j:j + 1] not in DELIM + WS:
            j += 1
        name = re.sub(rb"#([0-9a-fA-F]{2})",
                      lambda m: bytes([int(m.group(1), 16)]), buf[i + 1:j])
        return (b"name", name), j
    if c == b"(":
        j = skip_literal(buf, i)
        raw = buf[i + 1:j - 1]
        out = bytearray()
        k = 0
        mapping = {b"n": b"\n", b"r": b"\r", b"t": b"\t", b"b": b"\b",
                   b"f": b"\f", b"(": b"(", b")": b")", b"\\": b"\\"}
        while k < len(raw):
            ch = raw[k:k + 1]
            if ch == b"\\" and k + 1 < len(raw):
                nxt = raw[k + 1:k + 2]
                if nxt in mapping:
                    out += mapping[nxt]
                    k += 2
                    continue
                if nxt in b"01234567":
                    m = re.match(rb"[0-7]{1,3}", raw[k + 1:])
                    out += bytes([int(m.group(0), 8) & 0xFF])
                    k += 1 + len(m.group(0))
                    continue
                out += nxt
                k += 2
                continue
            out += ch
            k += 1
        return bytes(out), j
    if c == b"<":
        if buf[i:i + 2] == b"<<":
            return parse_dict(buf, i)
        j = buf.find(b">", i)
        if j < 0:
            raise ValueError("unterminated hex string")
        hexs = re.sub(rb"\s", b"", buf[i + 1:j])
        if len(hexs) % 2:
            hexs += b"0"
        try:
            return bytes.fromhex(hexs.decode("ascii")), j + 1
        except ValueError:
            return b"", j + 1
    if c == b"[":
        i2 = i + 1
        vals = []
        while True:
            i2 = skip_ws(buf, i2)
            if i2 >= n:
                raise ValueError("unterminated array")
            if buf[i2:i2 + 1] == b"]":
                return vals, i2 + 1
            v, i2 = parse_value(buf, i2)
            vals.append(v)
    if c in b"+-0123456789.":
        m2 = re.match(rb"(\d+)\s+(\d+)\s+R", buf[i:])
        if m2:
            return (int(m2.group(1)), int(m2.group(2))), i + m2.end()
        m = re.match(rb"[+-]?(?:\d+\.\d*|\.\d+|\d+)", buf[i:])
        if m:
            txt = m.group(0)
            if b"." in txt:
                return float(txt), i + len(txt)
            return int(txt), i + len(txt)
        raise ValueError("bad number")
    if buf.startswith(b"true", i):
        return True, i + 4
    if buf.startswith(b"false", i):
        return False, i + 5
    if buf.startswith(b"null", i):
        return None, i + 4
    raise ValueError(f"cannot parse value at {i}: {buf[i:i + 16]!r}")


def parse_dict(buf, i):
    """i points at '<<'; return (dict, index_after_>>)."""
    i += 2
    d = {}
    n = len(buf)
    while True:
        i = skip_ws(buf, i)
        if i + 1 < n and buf[i:i + 2] == b">>":
            return d, i + 2
        if i >= n or buf[i:i + 1] != b"/":
            raise ValueError(f"expected name key in dict at {i}")
        key_v, i = parse_value(buf, i)
        val, i = parse_value(buf, i)
        d[key_v[1]] = val


def rewrite_refs(blob, mapping):
    """Rewrite indirect references 'N G R' in non-stream content."""
    out = bytearray()
    i = 0
    n = len(blob)
    while i < n:
        c = blob[i:i + 1]
        if c == b"%":
            j = blob.find(b"\n", i)
            if j < 0:
                out += blob[i:]
                break
            out += blob[i:j + 1]
            i = j + 1
            continue
        if c == b"(":
            j = skip_literal(blob, i)
            out += blob[i:j]
            i = j
            continue
        if c == b"<":
            if blob[i:i + 2] == b"<<":
                out += b"<<"
                i += 2
                continue
            j = blob.find(b">", i)
            if j < 0:
                out += blob[i:]
                break
            out += blob[i:j + 1]
            i = j + 1
            continue
        if c.isdigit():
            m = REF_RE.match(blob, i)
            if m:
                old = int(m.group(1))
                new = mapping.get(old)
                if new is not None:
                    out += b"%d 0 R" % new
                else:
                    out += m.group(0)
                i = m.end()
                continue
        out += c
        i += 1
    return bytes(out)


class PdfDoc:
    def __init__(self, path):
        with open(path, "rb") as f:
            self.data = f.read()
        self.path = path
        self.entries = {}
        self.trailer = {}
        self.version = (1, 4)

    def parse(self):
        data = self.data
        m = re.search(rb"%PDF-(\d+)\.(\d+)", data[:2048])
        if m:
            self.version = (int(m.group(1)), int(m.group(2)))
        idx = data.rfind(b"startxref")
        if idx < 0:
            raise ValueError(f"{self.path}: no startxref found")
        m = re.search(rb"startxref\s+(\d+)", data[idx:])
        if not m:
            raise ValueError(f"{self.path}: malformed startxref")
        xref_pos = int(m.group(1))
        seen = set()
        while xref_pos and xref_pos not in seen:
            seen.add(xref_pos)
            xref_pos = self.parse_xref_at(xref_pos)
        if b"Root" not in self.trailer:
            raise ValueError(f"{self.path}: no /Root in trailer")

    def parse_xref_at(self, pos):
        data = self.data
        i = skip_ws(data, pos)
        if data[i:i + 4] == b"xref":
            return self.parse_classic_xref(i)
        return self.parse_xref_stream_at(pos)

    def parse_classic_xref(self, i):
        data = self.data
        i += 4
        while True:
            i = skip_ws(data, i)
            if data[i:i + 7] == b"trailer":
                d, _ = parse_dict(data, i + 7)
                self.trailer.update(d)
                break
            m = re.match(rb"(\d+)\s+(\d+)", data[i:i + 64])
            if not m:
                raise ValueError(f"{self.path}: bad xref subsection at {i}: "
                                 f"{data[i:i + 64]!r}")
            first = int(m.group(1))
            count = int(m.group(2))
            i += m.end()
            for e in range(count):
                line_end = data.find(b"\n", i)
                if line_end < 0:
                    line_end = len(data)
                line = data[i:line_end].rstrip(b"\r")
                fm = re.match(rb"(\d{10})\s+(\d{5})\s+([nf])", line)
                if not fm:
                    raise ValueError(f"{self.path}: bad xref entry at {i}: "
                                     f"{line[:60]!r}")
                offset = int(fm.group(1))
                gen = int(fm.group(2))
                typ = fm.group(3)
                num = first + e
                if typ == b"n" and offset > 0:
                    self.entries.setdefault(num, (gen, offset))
                i = line_end + 1
        xref_stm = self.trailer.get(b"XRefStm")
        if xref_stm is not None:
            stm_pos = int(xref_stm)
            self.parse_xref_stream_at(stm_pos, override=True)
        prev = self.trailer.get(b"Prev", 0)
        return int(prev)

    def parse_xref_stream_at(self, pos, override=False):
        data = self.data
        i = skip_ws(data, pos)
        m = re.match(rb"(\d+)\s+(\d+)\s+obj", data[i:i + 64])
        if not m:
            raise ValueError(f"{self.path}: bad xref stream object at {pos}")
        start = i + m.end()
        d = parse_value(data, start)[0]
        if not isinstance(d, dict):
            raise ValueError(f"{self.path}: xref stream header is not a dict")
        j, data_end, _ = self.stream_data_bounds(start, d)
        stm = self.decode_stream(data[j:data_end], d)
        self.parse_xref_stream_data(stm, d, override=override)
        for k in (b"Root", b"Info", b"Size", b"Prev", b"ID", b"XRefStm"):
            if k in d:
                self.trailer[k] = d[k]
        prev = d.get(b"Prev", 0)
        return int(prev)

    def parse_xref_stream_data(self, stm, d, override=False):
        W = [int(x) for x in d.get(b"W", [1, 2, 1])]
        size = int(d.get(b"Size", 0))
        index = d.get(b"Index", [0, size])
        w1, w2, w3 = W
        entry_len = w1 + w2 + w3

        def gi(rec, w):
            return int.from_bytes(rec[:w], "big") if w else 0

        for k in range(0, len(index), 2):
            start_num = index[k]
            count = index[k + 1]
            for e in range(count):
                off = e * entry_len
                rec = stm[off:off + entry_len]
                if len(rec) < entry_len:
                    break
                t = gi(rec, w1)
                f2 = gi(rec, w2)
                f3 = gi(rec, w3)
                num = start_num + e
                if num == 0:
                    continue
                if t == 1:
                    if override or num not in self.entries:
                        self.entries[num] = (f3, f2)
                elif t == 2:
                    if override or num not in self.entries:
                        self.entries[num] = ("stm", f2, f3)

    def resolve_int(self, v):
        if isinstance(v, int):
            return v
        if isinstance(v, tuple) and len(v) == 2 and isinstance(v[0], int):
            num = v[0]
            entry = self.entries.get(num)
            if entry is None:
                raise ValueError(f"{self.path}: cannot resolve /Length object {num}")
            if entry[0] == "stm":
                raw = self.extract_from_objstm(entry[1], entry[2])
            else:
                dict_part, stream_part = self.extract_object(num, entry[0], entry[1])
                raw = dict_part
            val = parse_value(raw, 0)[0]
            return int(val)
        raise ValueError("cannot resolve integer")

    def stream_data_bounds(self, dict_start, d):
        data = self.data
        si = find_keyword(data, dict_start, b"stream", prev_ws_only=True)
        if si < 0:
            raise ValueError(f"{self.path}: stream keyword not found")
        j = si + 6
        if data[j:j + 2] == b"\r\n":
            j += 2
        elif j < len(data) and data[j:j + 1] in (b"\r", b"\n"):
            j += 1
        length = None
        try:
            length = self.resolve_int(d.get(b"Length", 0))
        except Exception:
            length = None
        if length is not None and length >= 0:
            cand = j + length
            es = find_keyword(data, cand, b"endstream")
            if es >= 0 and es - cand <= 2:
                return j, cand, es
        es = find_keyword(data, j, b"endstream")
        if es < 0:
            raise ValueError(f"{self.path}: endstream not found")
        return j, es, es

    def decode_stream(self, raw, d):
        filt = d.get(b"Filter")
        filters = []
        if isinstance(filt, list):
            filters = [f[1] for f in filt if isinstance(f, tuple) and f[0] == b"name"]
        elif isinstance(filt, tuple) and filt[0] == b"name":
            filters = [filt[1]]
        for f in filters:
            if f in (b"FlateDecode", b"Fl"):
                raw = zlib.decompress(raw)
            else:
                raise ValueError(f"{self.path}: unsupported stream filter {f!r}")
        return raw

    def extract_object(self, num, gen, offset):
        data = self.data
        i = skip_ws(data, offset)
        m = re.match(rb"(\d+)\s+(\d+)\s+obj", data[i:i + 64])
        if not m:
            m2 = re.search(rb"\d+\s+\d+\s+obj", data[offset:offset + 256])
            if not m2:
                raise ValueError(f"{self.path}: object {num} marker not found at offset {offset}")
            i = offset + m2.start()
        start = i + m.end()
        si = find_keyword(data, start, b"stream", prev_ws_only=True)
        if si >= 0:
            dict_part = data[start:si]
            d = parse_value(dict_part, 0)[0]
            if not isinstance(d, dict):
                raise ValueError(f"{self.path}: stream object {num} has non-dict header")
            j, data_end, es = self.stream_data_bounds(start, d)
            eo = find_keyword(data, es + 9, b"endobj")
            if eo < 0:
                raise ValueError(f"{self.path}: object {num} has no endobj after endstream")
            return dict_part, data[j:data_end]
        eo = find_keyword(data, start, b"endobj")
        if eo < 0:
            raise ValueError(f"{self.path}: object {num} has no endobj")
        return data[start:eo], None

    def extract_from_objstm(self, stm_num, idx):
        entry = self.entries.get(stm_num)
        if entry is None or entry[0] == "stm":
            raise ValueError(f"{self.path}: bad object stream {stm_num}")
        dict_part, stream_part = self.extract_object(stm_num, entry[0], entry[1])
        d = parse_value(dict_part, 0)[0]
        raw = self.decode_stream(stream_part, d)
        n = int(d.get(b"N", 0))
        pairs = []
        i = 0
        for _ in range(n):
            i = skip_ws(raw, i)
            m = re.match(rb"(\d+)\s+(\d+)", raw[i:i + 64])
            if not m:
                raise ValueError(f"{self.path}: bad object stream header in {stm_num}")
            pairs.append((int(m.group(1)), int(m.group(2))))
            i += m.end()
        if idx >= len(pairs):
            raise ValueError(f"{self.path}: object stream index out of range")
        off = pairs[idx][1]
        end = pairs[idx + 1][1] if idx + 1 < len(pairs) else len(raw)
        return raw[off:end]

    def get_object_dict(self, num):
        entry = self.entries.get(num)
        if entry is None:
            raise ValueError(f"{self.path}: object {num} missing from xref")
        if entry[0] == "stm":
            raw = self.extract_from_objstm(entry[1], entry[2])
        else:
            dict_part, stream_part = self.extract_object(num, entry[0], entry[1])
            raw = dict_part
        val = parse_value(raw, 0)[0]
        if not isinstance(val, dict):
            raise ValueError(f"{self.path}: object {num} is not a dict")
        return val

    def collect_pages(self):
        root = self.trailer.get(b"Root")
        if not isinstance(root, tuple) or len(root) != 2:
            raise ValueError(f"{self.path}: bad /Root in trailer")
        root_obj = self.get_object_dict(root[0])
        pages_ref = root_obj.get(b"Pages")
        if not isinstance(pages_ref, tuple):
            raise ValueError(f"{self.path}: no /Pages in catalog")
        pages_num = pages_ref[0]
        leaves = []
        nodes = set()
        seen = set()

        def visit(num):
            if num in seen:
                return
            seen.add(num)
            d = self.get_object_dict(num)
            kids = d.get(b"Kids")
            if isinstance(kids, list) and kids:
                nodes.add(num)
                for kid in kids:
                    if isinstance(kid, tuple):
                        visit(kid[0])
            else:
                leaves.append(num)

        visit(pages_num)
        if not leaves:
            leaves = [pages_num]
        return leaves, nodes


def write_output(plans, kids, total, version):
    out = bytearray()
    out += b"%PDF-%d.%d\n" % version
    offsets = {}
    offsets[1] = len(out)
    out += b"1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n"
    offsets[2] = len(out)
    kids_bytes = b" ".join(b"%d 0 R" % k for k in kids)
    out += (b"2 0 obj\n<< /Type /Pages /Kids [%s] /Count %d >>\nendobj\n"
            % (kids_bytes, len(kids)))
    for new_num, content in plans:
        offsets[new_num] = len(out)
        out += b"%d 0 obj\n" % new_num
        out += content
        out += b"\nendobj\n"
    xref_pos = len(out)
    out += b"xref\n0 %d\n" % total
    out += b"0000000000 65535 f \n"
    for num in range(1, total):
        off = offsets.get(num)
        if off is None:
            out += b"0000000000 65535 f \n"
        else:
            out += b"%010d 00000 n \n" % off
    out += (b"trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n"
            % (total, xref_pos))
    with open(OUTPUT_FILE, "wb") as f:
        f.write(bytes(out))


def main():
    for name in INPUT_FILES:
        if not os.path.isfile(name):
            sys.exit(f"Missing input file: {name}")
    try:
        docs = []
        for path in INPUT_FILES:
            doc = PdfDoc(path)
            doc.parse()
            docs.append(doc)
            print(f"Parsed {path}: PDF {doc.version[0]}.{doc.version[1]}, "
                  f"{len(doc.entries)} objects", file=sys.stderr)
        version = max(d.version for d in docs)
        merged_kids = []
        plans = []
        next_num = 3
        for doc in docs:
            leaves, nodes = doc.collect_pages()
            print(f"  {doc.path}: {len(leaves)} page(s), "
                  f"{len(nodes)} pages node(s)", file=sys.stderr)
            mapping = {}
            new_num_for = {}
            for num in sorted(doc.entries):
                if num in nodes:
                    new_num_for[num] = 2
                else:
                    new_num_for[num] = next_num
                    next_num += 1
            mapping = dict(new_num_for)
            for num in sorted(doc.entries):
                if num in nodes:
                    continue
                entry = doc.entries[num]
                if entry[0] == "stm":
                    raw = doc.extract_from_objstm(entry[1], entry[2])
                    rewritten = rewrite_refs(raw, mapping)
                else:
                    dict_part, stream_part = doc.extract_object(num, entry[0], entry[1])
                    dict_rewritten = rewrite_refs(dict_part, mapping)
                    if stream_part is None:
                        rewritten = dict_rewritten
                    else:
                        rewritten = (dict_rewritten.rstrip(WS) + b"\nstream\n"
                                     + stream_part + b"\nendstream")
                plans.append((new_num_for[num], rewritten))
            merged_kids.extend(new_num_for[l] for l in leaves)
        write_output(plans, merged_kids, next_num, version)
        print(f"Merged {', '.join(INPUT_FILES)} into {OUTPUT_FILE} "
              "using pure-Python PDF merger")
    except Exception as exc:  # noqa: BLE001 - report the failure clearly
        sys.exit(f"Merge failed: {exc}")


if __name__ == "__main__":
    main()

